class SelectGroup extends HTMLElement {
  static formAssociated = true;                    // participates in forms
  #internals = this.attachInternals();
  connectedCallback() {
    this.attachShadow({ mode: "open" }).innerHTML = "<ul role='listbox'><slot></slot></ul>";
    this.shadowRoot.querySelector("slot")
        .addEventListener("slotchange", () => this.#sync());
  }
  #sync() { /* re-derive order/selection from assignedElements() */ }
}
